using System;
using System.Reflection;
using System.Security.Cryptography;
using System.Windows.Forms;
class OwnershipTest {
 static object Field(MainForm f,string n){return typeof(MainForm).GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);}
 static void Call(MainForm f,string n){typeof(MainForm).GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,null);}
 static string Hash(string p){using(var sha=SHA256.Create())using(var file=System.IO.File.OpenRead(p))return Convert.ToBase64String(sha.ComputeHash(file));}
 [STAThread] static void Main(){Native.SetProcessDpiAwarenessContext(new IntPtr(-4));AppDomain.CurrentDomain.SetData("DualSlide.ThrowStartupErrors",true);AppDomain.CurrentDomain.SetData("DualSlide.SettingsDirectory",System.IO.Path.GetFullPath(".build/test-settings"));string a=System.IO.Path.GetFullPath("test-master.pptx"),b=System.IO.Path.GetFullPath("test-follower.pptx");string ah=Hash(a),bh=Hash(b);dynamic app=Activator.CreateInstance(Type.GetTypeFromProgID("PowerPoint.Application")),existing=null;
 try{existing=app.Presentations.Open(a,-1,0,-1);existing.Slides[1].Shapes.AddTextbox(1,20,20,100,30).TextFrame.TextRange.Text="Unsaved ownership test";int shapeCount=existing.Slides[1].Shapes.Count;int count=app.Presentations.Count;using(var form=new MainForm()){form.Show();((ComboBox)Field(form,"masterPath")).Text=a;((ComboBox)Field(form,"followerPath")).Text=b;Call(form,"Start");if(!(bool)Field(form,"running"))throw new Exception("Start failed");dynamic master=Field(form,"master"),follower=Field(form,"follower");if((bool)Field(form,"ownMaster")||!(bool)Field(form,"ownFollower"))throw new Exception("Incorrect document ownership");if((string)master.FullName!=a||(string)follower.FullName!=b||(int)app.Presentations.Count!=count+1)throw new Exception("Unexpected presentation copy");Console.WriteLine("PASS: actual filenames, existing presenter reused, no untitled session copies.");Call(form,"Stop");Console.WriteLine("AFTER count="+app.Presentations.Count+" expected="+count+" shapes="+existing.Slides[1].Shapes.Count+" expected="+shapeCount+" saved="+existing.Saved);if((int)app.Presentations.Count!=count||(int)existing.Slides[1].Shapes.Count!=shapeCount||(int)existing.Saved!=0)throw new Exception("Existing document or unsaved changes affected");form.Close();}Console.WriteLine("PASS: existing presentation and unsaved edits preserved; only owned deck closed.");if(ah!=Hash(a)||bh!=Hash(b))throw new Exception("Source bytes changed");Console.WriteLine("PASS: source file hashes unchanged.");}
 catch(Exception ex){Console.WriteLine("FAIL: "+ex);Environment.ExitCode=1;}finally{try{existing.Saved=-1;existing.Close();}catch{}}}
}
